//! Synthetic physical capacity only: production limits remain unchanged. The
//! protected ACK/reference/Delivered are generated by real source store IO from
//! signed fixtures; filler files are explicitly not authenticated source events.
use super::*;

fn compact_usage(store: &PendingFinalityStore) -> (usize, u64) {
    let paths =
        store.paths().expect("physical directory must remain within its own admission limits");
    let compact: Vec<_> = paths
        .iter()
        .filter(|p| {
            matches!(p.extension().and_then(|s| s.to_str()), Some("reference" | "delivered"))
        })
        .collect();
    (compact.len(), compact.iter().map(|p| std::fs::metadata(p).unwrap().len()).sum())
}
fn unchanged(protected: &[(PathBuf, Vec<u8>)]) {
    for (path, bytes) in protected {
        assert_eq!(
            &std::fs::read(path).unwrap(),
            bytes,
            "{} changed on rejected transition",
            path.display()
        );
    }
}
fn capacity_case(by_count: bool) {
    let (_directory, runtime, store, record, offer) = super::tests::setup();
    let namespace = store.directory.parent().unwrap().to_owned();
    let target = record.id().unwrap();
    let ack = store.directory.join(format!("{}.acked", target.to_hex_string()));
    let ack_bytes = std::fs::read(&ack).unwrap();
    store.compact(&record, offer.request.canonical.node_receipt.clone()).unwrap();
    // A genuine older ACK backup may coexist with its canonical reference.
    std::fs::write(&ack, &ack_bytes).unwrap();
    File::open(&ack).unwrap().sync_all().unwrap();
    File::open(&store.directory).unwrap().sync_all().unwrap();
    let reference = store.close_locator(&target).unwrap().unwrap().reference;
    let reference_path = store.reference_path(&target);
    // Keep a distinct, fully source-synced Delivered record as protected history.
    let (other_runtime, draft) =
        super::super::tests::fixture_seqno(true, runtime.shard().clone(), 2);
    assert_eq!(other_runtime.session_id(), runtime.session_id());
    let history = PendingFinalityRecord::from_draft(&runtime, &draft).unwrap();
    let history_id = history.id().unwrap();
    assert_ne!(target, history_id);
    store.retain(&history).unwrap();
    store.acknowledge(&history_id, UInt256::from([0x55; 32])).unwrap();
    let history_ref = store.close_locator(&history_id).unwrap().unwrap().reference;
    let history_offer =
        CloseOffer { request: reference_request(&history_ref).unwrap(), generation: 2 };
    drop(store.commit_delivered(&runtime, &history_ref, &history_offer).unwrap());
    let history_path = store.delivered_path(&history_id);
    let protected = vec![
        (ack.clone(), ack_bytes),
        (reference_path.clone(), std::fs::read(&reference_path).unwrap()),
        (history_path.clone(), std::fs::read(&history_path).unwrap()),
    ];
    let target_size = serde_json::to_vec(&DeliveredDisk {
        schema: 1,
        reference: reference.clone(),
        generation: offer.generation,
        node_confirmed: false,
    })
    .unwrap()
    .len() as u64;
    let parent = store.directory.join(REFERENCE_DIRECTORY);
    let (base_count, base_bytes) = compact_usage(&store);
    assert_eq!(base_count, 2);
    let mut fillers = Vec::new();
    let filler_bytes = if by_count {
        0
    } else {
        (MAX_REFERENCE_TOTAL - MAX_REFERENCE_BYTES).checked_sub(target_size + base_bytes).unwrap()
            + 1
    };
    let filler_count = if by_count {
        MAX_REFERENCES - 1 - base_count
    } else {
        filler_bytes.div_ceil(MAX_REFERENCE_BYTES) as usize
    };
    let mut remaining = filler_bytes;
    for index in 0..filler_count {
        let path = parent.join(format!("{index:064x}.reference"));
        assert!(!path.exists(), "filler must never overwrite real protected evidence");
        let size = remaining.min(MAX_REFERENCE_BYTES);
        File::create(&path).unwrap().set_len(size).unwrap();
        remaining -= size;
        fillers.push(path);
    }
    assert_eq!(remaining, 0);
    let (count, bytes) = compact_usage(&store);
    if by_count {
        assert_eq!(count, MAX_REFERENCES - 1);
        assert!(bytes + target_size < MAX_REFERENCE_TOTAL - MAX_REFERENCE_BYTES);
    } else {
        assert!(count < MAX_REFERENCES - 1);
        assert_eq!(bytes + target_size, MAX_REFERENCE_TOTAL - MAX_REFERENCE_BYTES + 1);
    }
    let reject = |store: &PendingFinalityStore| {
        let error = match store.commit_delivered(&runtime, &reference, &offer) {
            Ok(_) => panic!("transition must reject without using its reserved capacity"),
            Err(error) => error,
        };
        assert_eq!(
            error.to_string(),
            "Delivered history capacity exhausted",
            "must reach the transition reserve branch, not paths/schema limits"
        );
        unchanged(&protected);
        assert!(!store.delivered_path(&target).exists());
        assert!(!store.delivered_path(&target).with_extension("tmp").exists());
        assert_eq!(compact_usage(store), (count, bytes));
    };
    reject(&store);
    drop(store);
    let store = PendingFinalityStore::open(&namespace).unwrap();
    // Capacity rejection is not an uncertain write; cold open retains exactly
    // the same evidence and still rejects at the same transition boundary.
    reject(&store);
    let last = fillers.last().unwrap();
    if by_count {
        std::fs::remove_file(last).unwrap();
    } else {
        let file = OpenOptions::new().write(true).open(last).unwrap();
        file.set_len(file.metadata().unwrap().len() - 1).unwrap();
    }
    let (allowed_count, allowed_bytes) = compact_usage(&store);
    if by_count {
        assert_eq!(allowed_count, MAX_REFERENCES - 2);
    } else {
        assert_eq!(allowed_bytes + target_size, MAX_REFERENCE_TOTAL - MAX_REFERENCE_BYTES);
    }
    drop(store.commit_delivered(&runtime, &reference, &offer).unwrap());
    assert!(!ack.exists());
    assert!(!reference_path.exists());
    assert_eq!(std::fs::read(&history_path).unwrap(), protected[2].1);
    let delivered_path = store.delivered_path(&target);
    let delivered = std::fs::read(&delivered_path).unwrap();
    drop(store);
    let store = PendingFinalityStore::open(&namespace).unwrap();
    // Existing Delivered does not require another transition reservation;
    // repeat real file+directory sync without refreshing its persisted bytes.
    drop(store.commit_delivered(&runtime, &reference, &offer).unwrap());
    assert_eq!(std::fs::read(delivered_path).unwrap(), delivered);
    assert_eq!(std::fs::read(history_path).unwrap(), protected[2].1);
}

#[test]
fn source_delivered_count_transition_reserve_exact_boundary_and_cold_retry() {
    capacity_case(true);
}
#[test]
fn source_delivered_bytes_transition_reserve_exact_boundary_and_cold_retry() {
    capacity_case(false);
}
